gHr(){return"\u042f \u043e\u0437\u043d\u0430\u0439\u043e\u043c\u0438\u0432\u0441\u044f(-\u043b\u0430\u0441\u044f) \u0437 \u0446\u0438\u043c\u0438 \u0443\u043c\u043e\u0432\u0430\u043c\u0438 \u0442\u0430 \u0437\u043e\u0431\u043e\u0432\u2019\u044f\u0437\u0443\u044e\u0441\u044f \u043f\u043e\u0432\u043d\u0456\u0441\u0442\u044e \u0432\u0438\u043a\u043e\u043d\u0430\u0442\u0438 \u0441\u0432\u043e\u044e \u0447\u0430\u0441\u0442\u0438\u043d\u0443 \u0446\u0456\u0454\u0457 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u043e\u0441\u0442\u0456 \u044f\u043a \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0435\u0446\u044c."},
gHo(){return"\u041f\u0456\u0434\u043f\u0438\u0441\u0430\u0442\u0438 \u0439 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u0438"},
gHs(){return"\u0412\u0438 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454\u0442\u0435, \u0449\u043e \u043f\u0440\u0438\u0439\u043c\u0430\u0454\u0442\u0435 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0432 \u0440\u043e\u0431\u043e\u0442\u0443 \u043d\u0430 \u0443\u043c\u043e\u0432\u0430\u0445 \u043f\u0456\u0434\u043f\u0438\u0441\u0430\u043d\u043e\u0457 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u0457?"},
gHV(){return"\u0412\u0456\u0434\u043a\u043b\u0438\u043a\u0430\u0442\u0438 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044e \u0442\u0430 \u0432\u0456\u0434\u043c\u043e\u0432\u0438\u0442\u0438\u0441\u044f \u0432\u0456\u0434 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f?"},
gHU(){return"\u0426\u0435 \u0430\u043d\u0443\u043b\u044e\u0454 \u0437\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u043e\u0432\u0430\u043d\u0443 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044c. \u0412\u0430\u0448\u0443 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044e \u0431\u0443\u0434\u0435 \u0432\u0456\u0434\u043a\u043b\u0438\u043a\u0430\u043d\u043e, \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a \u043e\u0442\u0440\u0438\u043c\u0430\u0454 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f, \u0430 \u0434\u0456\u044e \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0431\u0443\u0434\u0435 \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438."},
gHT(){return"\u0410\u043d\u0443\u043b\u044e\u0432\u0430\u0442\u0438 \u0439 \u0432\u0456\u0434\u043a\u043b\u0438\u043a\u0430\u0442\u0438"},
gHW(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0438\u0442\u0438 \u0443\u043c\u043e\u0432\u0438 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u0457. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0437\u2019\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0442\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0440\u043e\u0431\u0443."},
gI1(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0437\u0431\u0435\u0440\u0435\u0433\u0442\u0438 \u0440\u0456\u0448\u0435\u043d\u043d\u044f. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0442\u043e\u0447\u043d\u0438\u0439 \u0441\u0442\u0430\u043d \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0442\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0440\u043e\u0431\u0443."},
gHY(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u043f\u043e\u0437\u043d\u0430\u0447\u0438\u0442\u0438 \u0441\u043f\u043e\u0432\u0456\u0449\u0435\u043d\u043d\u044f \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u0438\u043c \u2014 \u0432\u043e\u043d\u043e \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u0437\u043d\u043e\u0432\u0443 \u043f\u0456\u0437\u043d\u0456\u0448\u0435."},
