Ht(a){return"\u0412\u0438\u043a\u043e\u043d\u0430\u0432\u0435\u0446\u044c \u043f\u0440\u0438\u0439\u043d\u044f\u0432 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \xab"+a+"\xbb. \u0412\u043e\u043d\u043e \u043f\u0435\u0440\u0435\u0432\u0435\u0434\u0435\u043d\u0435 \u0432 \u0441\u0442\u0430\u0442\u0443\u0441 \xab\u0423 \u0440\u043e\u0431\u043e\u0442\u0456\xbb."},
gHu(){return"\u0417\u0432\u2019\u044f\u0436\u0456\u0442\u044c\u0441\u044f \u0437 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u0435\u043c \u0456 \u0449\u0435 \u0440\u0430\u0437 \u0443\u0437\u0433\u043e\u0434\u044c\u0442\u0435 \u0434\u0430\u0442\u0443 \u0439 \u0447\u0430\u0441 \u043f\u043e\u0447\u0430\u0442\u043a\u0443, \u0434\u043e\u0441\u0442\u0443\u043f, \u043e\u0431\u0441\u044f\u0433 \u0442\u0430 \u0456\u043d\u0448\u0456 \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u043d\u0456 \u0434\u0435\u0442\u0430\u043b\u0456."},
